    EnTextos.textMsjInfoVibradores,
    'عندما يتم تنشيط الإدخال الرقمي لمحرك الصومعة، يبدأ "وقت المراقبة" في العد، وإذا لم يحدث "تغيير الوزن" خلال هذا الوقت، يتم تنشيط "مرحل الهزاز" لـ "وقت الهزاز". عند انقضاء هذا الوقت، سيتم تكرار العملية. عند اكتمال جميع عمليات التكرار، سيتم تنشيط "Silo Stop Relay" وسيتم عرض تحذير الهزاز. لاستئناف التشغيل، يجب مسح التحذيرات.'
